import { path, FileSystem, type Logger } from '@servicenow/sdk-build-core'
import { getAttachmentContent } from '../source-artifact-utils'
import { createNowPackIgnoreFilter, NOW_PACK_IGNORE_FILE } from '../now-pack-ignore-utils'

export type ProjectSourceFiles = {
    // Project-relative paths whose content is read from disk.
    sourceFiles: string[]
}

/**
 * Reads the source-file inputs from `_project.json` for the app source artifact.
 *
 * @returns an empty list when `_project.json` is absent.
 * @throws {Error} if `_project.json` is present but cannot be read or parsed — a corrupt file
 *   fails hard rather than silently producing a build with no editable source, which would
 *   otherwise look identical to the legitimate case where no source files exist.
 */
export function readProjectJsonSourceFiles(fs: FileSystem, metadataDir: string): ProjectSourceFiles {
    const projectJsonPath = path.join(metadataDir, '_project.json')
    if (!FileSystem.existsSync(fs, projectJsonPath)) {
        return { sourceFiles: [] }
    }

    const content = fs.readFileSync(projectJsonPath, { encoding: 'utf-8' }).toString()
    const parsed = JSON.parse(content) as {
        sourceFiles?: string[]
    }
    return {
        sourceFiles: parsed.sourceFiles ?? [],
    }
}

export type SourceArtifactFiles = {
    files: Map<string, Buffer>
    totalSize: number
    skippedFiles: string[]
}

/**
 * Assembles the set of files for the AIUX source artifact from _project.json.
 *
 * Reads `sourceFiles` (project-relative paths) from disk under `projectDir`.
 *
 * @returns the file map, total size, and skipped-file warnings — or `null` when there are
 *   no source files to attach at all.
 * @throws {Error} if the combined size would exceed `MAX_TOTAL_SIZE`, or if `_project.json` is
 *   present but cannot be read or parsed (see {@link readProjectJsonSourceFiles}).
 */
export async function collectSourceArtifactFiles(
    fs: FileSystem,
    {
        metadataDir,
        projectDir,
        useNowPackIgnore = false,
        logger,
    }: { metadataDir: string; projectDir: string; useNowPackIgnore?: boolean; logger?: Logger }
): Promise<SourceArtifactFiles | null> {
    const { sourceFiles } = readProjectJsonSourceFiles(fs, metadataDir)
    if (sourceFiles.length === 0) {
        return null
    }

    return getAttachmentContent(fs, projectDir, sourceFiles, useNowPackIgnore, logger)
}

/**
 * Resolves a zip entry key to an absolute path so it can be compared to a project path.
 *
 * Entry keys come verbatim from the `sourceFiles` array in `_project.json`, so the same file may be
 * written as `src/x/keys.ts`, `./src/x/keys.ts`, `/src/x/keys.ts`, or with backslashes. This
 * mirrors how {@link getAttachmentContent} turned the entry into a path to read from: strip a
 * leading separator, then resolve against the project directory. Comparing resolved paths rather
 * than normalized strings is what makes the match immune to how the entry happens to be spelled.
 */
function toAbsolutePath(entry: string, projectDir: string): string {
    return path.resolve(projectDir, entry.replace(/\\/g, '/').replace(/^\/+/, ''))
}

/**
 * Puts the project's in-memory `keys.ts` into the artifact, replacing the packaged copy or adding
 * one when the artifact carries none.
 *
 * The `keys.ts` on disk is stale for the entire build: the keys registry is only serialized into
 * its source file once every record has been collected, and that file is only written to disk
 * after the output XML has been generated. An artifact assembled from disk therefore ships the
 * *previous* build's sys_ids, so any record this build added — a new widget or page — is missing
 * from the source the instance receives. The committed source file text is the only place the ids
 * this build actually produced can be read from.
 *
 * An entry is ours when it resolves to `keysFilePath`, however it is spelled (see
 * {@link toAbsolutePath}); one that resolves anywhere else is a different file — a nested package's
 * registry, or an entry rooted somewhere other than `projectDir` — and is left alone rather than
 * being overwritten with this project's registry.
 *
 * When no entry is ours the registry is **added**, because `_project.json` cannot be the authority
 * on this one file: a freshly scaffolded project has no `keys.ts` until its first build writes one,
 * so the prebuild that listed the source files had nothing to list. Shipping that artifact without
 * a registry is worse than an outdated one — the source cannot resolve any of the ids the instance
 * was just given, and rebuilding from it mints new ones and orphans every record. Adding is skipped
 * only where it would be wrong: a registry outside `projectDir` has no valid entry key, and a
 * `{@link NOW_PACK_IGNORE_FILE}` rule covering it is an explicit opt-out that outranks the refresh.
 * Entries already in `files` needed no such check — they were vetted against the same rules when
 * they were collected.
 *
 * @returns the patched file map, its recomputed total size, and the entry holding the registry —
 *   `undefined` when the artifact was left without one.
 */
export function replaceKeysFileContent(
    files: Map<string, Buffer>,
    {
        keysFilePath,
        keysContent,
        projectDir,
        fs,
    }: { keysFilePath: string; keysContent: string | undefined; projectDir: string; fs: FileSystem }
): { files: Map<string, Buffer>; totalSize: number; keysEntry: string | undefined } {
    const patched = new Map(files)
    let keysEntry: string | undefined

    if (keysContent !== undefined) {
        const target = path.resolve(keysFilePath)
        keysEntry = [...files.keys()].find((entry) => toAbsolutePath(entry, projectDir) === target)

        if (keysEntry === undefined) {
            const relativeEntry = path.relative(projectDir, target)
            if (!relativeEntry.startsWith('..') && createNowPackIgnoreFilter(fs, projectDir)(relativeEntry)) {
                keysEntry = relativeEntry
            }
        }

        if (keysEntry !== undefined) {
            patched.set(keysEntry, Buffer.from(keysContent, 'utf-8'))
        }
    }

    // Recomputed rather than adjusted so `size_bytes` always matches what is actually zipped. The
    // total was already checked against MAX_TOTAL_SIZE when the files were read; swapping or adding
    // a keys registry moves the total by that one file, which is a matter of bytes per record.
    let totalSize = 0
    for (const content of patched.values()) {
        totalSize += content.length
    }

    return { files: patched, totalSize, keysEntry }
}
